#!/usr/bin/env python3
"""Offline campaign entry point: targets, capture census, follow-up certificate."""
import json
from pathlib import Path
import os
import sys
import tempfile
sys.path.insert(0,str(Path(__file__).resolve().parent))
sys.path.insert(0,str(Path(__file__).resolve().parent.parent/'deps'))

from common import CaptureError,Invalid,parse_json,validate
from gen_targets import plan
from classify_responses import capture_records
from census import build
from planning import solve


def audit(job):
    context=validate(job)
    manifest,lookup,low=plan(context['leases'],context['seed'])
    with tempfile.TemporaryDirectory(prefix='campaign-',dir=os.environ.get('TMPDIR','/workspace/tmp')) as directory:
        records,rejected=capture_records(context,lookup,Path(directory))
    snapshots,active=build(context,records,low)
    result=solve(context,active)
    return {'manifest':manifest,'rejected':rejected,'snapshots':snapshots,
            'active_requests':[{'id':name,'active':active[name]} for name in sorted(active)],
            'plan':result}


def main():
    try:
        raw=sys.stdin.buffer.read(64*1024**2+1)
        if len(raw)>64*1024**2:
            raise Invalid('input byte budget')
        result=audit(parse_json(raw))
    except NotImplementedError:
        result={'error':'not_implemented'}
    except CaptureError:
        result={'error':'capture'}
    except (Invalid,ValueError,TypeError,KeyError,RecursionError):
        result={'error':'invalid'}
    sys.stdout.write(json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False)+'\n')


if __name__=='__main__':main()
"""Shared wire types and bounded metadata for the offline campaign tools."""
import base64
import binascii
import ipaddress
import json
import re

DOC = ipaddress.IPv6Network('2001:db8::/32')
ID = re.compile(r'[A-Za-z0-9_-]{1,24}\Z')
COLUMNS = ('type','id','revision','published','op','lease','event','probe',
           'target','responder','result','service','attempt','payload')
MAX_TIME = 10**12


class Invalid(ValueError):
    pass


class CaptureError(ValueError):
    pass


def need(condition):
    if not condition:
        raise Invalid('invalid metadata')


def ident(value):
    return isinstance(value,str) and ID.fullmatch(value) is not None


def integer(value,low=0,high=MAX_TIME):
    return type(value) is int and low <= value <= high


def fields(value,names):
    return type(value) is dict and set(value)==set(names.split())


def address(text):
    need(isinstance(text,str) and len(text)<=64 and '%' not in text
         and not any(c.isspace() for c in text))
    try:
        value=ipaddress.IPv6Address(text)
    except ValueError:
        raise Invalid('invalid IPv6 address') from None
    need(value in DOC)
    return int(value)


def prefix(text,lengths=None):
    need(isinstance(text,str) and len(text)<=80 and '%' not in text
         and not any(c.isspace() for c in text))
    try:
        value=ipaddress.IPv6Network(text,strict=True)
    except ValueError:
        raise Invalid('invalid IPv6 prefix') from None
    need(value.subnet_of(DOC) and (lengths is None or value.prefixlen in lengths))
    return value


def addresses(values):
    return [str(ipaddress.IPv6Address(n)) for n in sorted(values)]


def decimal(text,high=MAX_TIME):
    need(isinstance(text,str) and 1<=len(text)<=16 and text.isascii() and text.isdecimal())
    n=int(text)
    need(n<=high)
    return n


def decode64(text,error=Invalid):
    if not isinstance(text,str):
        raise error('invalid base64')
    try:
        return base64.b64decode(text.encode('ascii'),validate=True)
    except (ValueError,UnicodeError,binascii.Error):
        raise error('invalid base64') from None


def unique(pairs):
    result={}
    for key,value in pairs:
        need(key not in result)
        result[key]=value
    return result


def parse_json(data):
    try:
        return json.loads(data.decode('utf-8'),object_pairs_hook=unique,
                          parse_constant=lambda _: (_ for _ in ()).throw(Invalid()))
    except (ValueError,UnicodeError,RecursionError):
        raise Invalid('invalid JSON') from None


def forest(items):
    need(type(items) is list and len(items)<=4096)
    nodes={}
    for row in items:
        need(fields(row,'id parent capacity') and ident(row['id']))
        need(row['id'] not in nodes and integer(row['capacity'],0,4096))
        need(row['parent'] is None or ident(row['parent']))
        nodes[row['id']]=dict(row)
    paths={}
    for node in nodes:
        seen=[]
        at=node
        while at is not None:
            need(at in nodes and at not in seen and len(seen)<32)
            seen.append(at)
            at=nodes[at]['parent']
        paths[node]=tuple(seen)
    return nodes,paths


def validate(job):
    need(fields(job,'version seed leases services queries captures requests offers request_quotas offer_quotas'))
    need(type(job['version']) is int and job['version']==3 and ident(job['seed']))
    queries=job['queries']
    need(type(queries) is list and 1<=len(queries)<=4)
    need(all(integer(q) for q in queries) and len(set(queries))==len(queries))
    services={}
    need(type(job['services']) is list and len(job['services'])<=8)
    for row in job['services']:
        need(fields(row,'id kind') and ident(row['id']) and row['id'] not in services)
        need(row['kind'] in ('tcp','adb','sync'))
        services[row['id']]=row['kind']
    leases={}
    target_count=0
    need(type(job['leases']) is list and len(job['leases'])<=2048)
    for row in job['leases']:
        need(fields(row,'id prefix start end subnets low_count'))
        need(ident(row['id']) and row['id'] not in leases)
        need(integer(row['start']) and integer(row['end'],1,MAX_TIME+1)
             and row['start']<row['end'])
        net=prefix(row['prefix'],(56,64))
        subs=row['subnets']
        need(type(subs) is list and 1<=len(subs)<=16)
        need(all(integer(s,0,255 if net.prefixlen==56 else 0) for s in subs)
             and len(set(subs))==len(subs))
        need(integer(row['low_count'],1,32))
        target_count+=len(subs)*(row['low_count']+1)
        leases[row['id']]={**row,'network':net,'subnets':sorted(subs)}
    need(target_count<=65536)
    captures=job['captures']
    need(type(captures) is list and len(captures)<=16)
    nchunks=0
    for capture in captures:
        need(fields(capture,'encoding chunks') and capture['encoding'] in ('csv','zstd'))
        need(type(capture['chunks']) is list and all(isinstance(x,str) for x in capture['chunks']))
        nchunks+=len(capture['chunks'])
    need(nchunks<=1024)
    rq,rpaths=forest(job['request_quotas'])
    oq,opaths=forest(job['offer_quotas'])
    requests={}
    need(type(job['requests']) is list and len(job['requests'])<=4096)
    for row in job['requests']:
        need(fields(row,'id at lease target service group'))
        need(ident(row['id']) and row['id'] not in requests)
        need(integer(row['at']) and row['at'] in queries and row['lease'] in leases)
        need(row['service'] in services and row['group'] in rq)
        requests[row['id']]={**row,'address':address(row['target'])}
    offers={}
    pairs=0
    need(type(job['offers']) is list and len(job['offers'])<=8192)
    for row in job['offers']:
        need(fields(row,'id time service prefix capacity cost group requests'))
        need(ident(row['id']) and row['id'] not in offers)
        need(integer(row['time']) and row['service'] in services)
        need(integer(row['capacity'],0,4096) and integer(row['cost'],0,10**9))
        need(row['group'] in oq and type(row['requests']) is list)
        need(all(isinstance(x,str) and x in requests for x in row['requests']))
        need(len(set(row['requests']))==len(row['requests']))
        pairs+=len(row['requests'])
        offers[row['id']]={**row,'network':prefix(row['prefix'])}
    need(pairs<=262144)
    return {'seed':job['seed'],'leases':leases,'services':services,
            'queries':sorted(queries),'captures':captures,'requests':requests,
            'offers':offers,'request_quotas':rq,'request_paths':rpaths,
            'offer_quotas':oq,'offer_paths':opaths}

#!/usr/bin/env python3
"""Expand a list of IPv6 prefixes into /128 targets for ZMap6.

For each prefix in the input file, emit N+1 targets: one canary target
(used to detect aliased prefixes that respond to every probe) followed
by N sequentially-numbered IIDs (::1, ::2, ..., ::N).

The canary IID is randomized per run by default and printed to stderr
so it can be passed to downstream tooling that filters aliased
responders.

Input prefixes must be written so that prefix + ":<64-bit IID>" is a
valid IPv6 address — i.e. four colon-separated groups for /56 input
(e.g. "2001:0000:0192:7d00").
"""
import argparse
import random
import sys
import hashlib
import ipaddress


def random_iid() -> str:
    h = "%016x" % random.getrandbits(64)
    return ":".join(h[i:i + 4] for i in range(0, 16, 4))


def format_iid(value: int) -> str:
    h = "%016x" % value
    return ":".join(h[i:i + 4] for i in range(0, 16, 4))


def plan(leases, seed):
    """Expand campaign leases using the toolkit's canary/low-IID target loop."""
    manifest=[]
    lookup={}
    low={}
    for lease_id in sorted(leases):
        lease=leases[lease_id]
        low[lease_id]=set()
        for subnet in lease['subnets']:
            base=int(lease['network'].network_address)+(subnet<<64)
            network=str(ipaddress.IPv6Network((base,64)))
            material='\n'.join((seed,lease_id,network)).encode('utf-8')
            canary=int.from_bytes(hashlib.sha256(material).digest()[:8],'big')|(1<<63)
            prefix=':'.join(ipaddress.IPv6Address(base).exploded.split(':')[:4])
            slots=[('c',canary)]+[(f'i{i}',i) for i in range(1,lease['low_count']+1)]
            for slot,value in slots:
                target=int(ipaddress.IPv6Address(f'{prefix}:{format_iid(value)}'))
                probe=f'{subnet}/{slot}'
                manifest.append({'lease':lease_id,'probe':probe,
                                 'target':str(ipaddress.IPv6Address(target))})
                lookup[(lease_id,probe)]=(target,slot=='c')
                if slot!='c':
                    low[lease_id].add(target)
    return manifest,lookup,low


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("input_file", help="file of IPv6 prefixes, one per line")
    parser.add_argument("output_file", help="file to write ZMap6 targets to")
    parser.add_argument("num_targets", type=int,
                        help="sequential IID targets to generate per prefix")
    parser.add_argument("--canary",
                        help="canary IID (default: random per run)")
    args = parser.parse_args()

    if args.num_targets < 1:
        parser.error("num_targets must be at least 1")
    if args.num_targets >= (1 << 64):
        parser.error("num_targets is too large")

    canary = args.canary or random_iid()
    print(f"canary IID: {canary}", file=sys.stderr)

    with open(args.input_file) as infile, open(args.output_file, "w") as outfile:
        for line in infile:
            prefix = line.strip()
            if not prefix:
                continue
            outfile.write(f"{prefix}:{canary}\n")
            for i in range(1, args.num_targets + 1):
                outfile.write(f"{prefix}:{format_iid(i)}\n")


if __name__ == "__main__":
    main()
#!/usr/bin/env python3
"""Group ZMap6 responses by /64 network and classify each as internal or external.

A response is "internal" when the responder address equals the probed
target — the probe came back from the address we aimed at. It is
"external" when a different address responded (typically a CPE,
router, or NAT64 box on a neighboring address).

Aliased /64 prefixes listed in `aliases_file` are skipped, since they
respond to every probe and would pollute the classification.

Output: JSON Lines on stdout, one record per /64 network:

    {"network": "<4 colon groups>", "internal": [...], "external": [...]}

Usage:
    classify-responses.py aliases.txt zmap-output.csv.zst > networks.jsonl
"""
import argparse
import csv
import io
import ipaddress
import json

import zstandard as zstd
from common import COLUMNS,CaptureError,Invalid,decode64
from ledger import parse_record


def stream_csv(path,encoding='zstd',budget=None,logical_records=False):
    with open(path, "rb") as fh:
        reader=(zstd.ZstdDecompressor().stream_reader(fh,read_across_frames=True)
                if encoding=='zstd' else fh)
        bounded=io.BufferedReader(BoundedReader(reader,budget)) if budget is not None else reader
        with io.TextIOWrapper(bounded,encoding='utf-8',newline='') as text:
            if logical_records:
                yield from csv.reader(text,strict=True)
            else:
                for line in text:
                    if line.startswith('saddr'):
                        continue
                    yield line


class BoundedReader(io.RawIOBase):
    def __init__(self,source,budget):
        self.source=source
        self.budget=budget

    def readable(self):
        return True

    def readinto(self,buffer):
        block=self.source.read(min(len(buffer),self.budget[0]+1))
        self.budget[0]-=len(block)
        if self.budget[0]<0:
            raise CaptureError('decompressed byte budget')
        buffer[:len(block)]=block
        return len(block)


def complete_frames(data):
    """Validate complete dictionary-free bounded-window Zstandard framing."""
    at=0
    while at<len(data):
        if at+4>len(data):raise CaptureError('truncated Zstandard magic')
        magic=int.from_bytes(data[at:at+4],'little')
        if 0x184d2a50<=magic<=0x184d2a5f:
            if at+8>len(data):raise CaptureError('truncated skippable frame')
            size=int.from_bytes(data[at+4:at+8],'little');at+=8+size
            if at>len(data):raise CaptureError('truncated skippable frame')
            continue
        if magic!=0xfd2fb528 or at+5>len(data):raise CaptureError('invalid Zstandard frame')
        flag=data[at+4]
        if flag&0x08:raise CaptureError('reserved Zstandard frame bit')
        single=bool(flag&0x20)
        dictionary=(0,1,2,4)[flag&3]
        content=(1 if single else 0,2,4,8)[flag>>6]
        header=5+(not single)+dictionary+content
        if at+header>len(data):raise CaptureError('truncated Zstandard header')
        params=zstd.get_frame_parameters(data[at:at+header])
        if params.dict_id or params.window_size>128*1024**2:
            raise CaptureError('unsupported dictionary or window')
        at+=header
        while True:
            if at+3>len(data):raise CaptureError('truncated Zstandard block')
            block=int.from_bytes(data[at:at+3],'little');at+=3
            kind=(block>>1)&3;size=block>>3
            if kind==3:raise CaptureError('reserved Zstandard block type')
            at+=1 if kind==1 else size
            if at>len(data):raise CaptureError('truncated Zstandard block')
            if block&1:break
        if flag&4:at+=4
        if at>len(data):raise CaptureError('truncated Zstandard checksum')


def capture_records(context,lookup,scratch):
    """Read the actual compressed CSV path with bounded, logical-record parsing."""
    csv.field_size_limit(131072)
    records=[]
    rejected=[]
    decoded=0
    count=0
    budget=[128*1024**2]
    for number,capture in enumerate(context['captures']):
        blocks=[decode64(text,CaptureError) for text in capture['chunks']]
        decoded+=sum(map(len,blocks))
        if decoded>32*1024**2:
            raise CaptureError('decoded byte budget')
        if capture['encoding']=='zstd':
            try:complete_frames(b''.join(blocks))
            except zstd.ZstdError as exc:raise CaptureError('invalid Zstandard header') from exc
        path=scratch/f'capture-{number}.bin'
        with path.open('wb') as output:
            for block in blocks:
                output.write(block)
        del blocks
        try:
            rows=stream_csv(path,capture['encoding'],budget,logical_records=True)
            if next(rows,None)!=list(COLUMNS):
                raise CaptureError('invalid CSV header')
            for ordinal,values in enumerate(rows):
                count+=1
                if count>200000 or any(len(v.encode('utf-8'))>131072 for v in values):
                    raise CaptureError('capture record budget')
                try:
                    row=parse_record(values,context,lookup)
                except (Invalid,ValueError,TypeError):
                    rejected.append([number,ordinal])
                    continue
                records.append(row)
        except (UnicodeError,csv.Error,zstd.ZstdError,EOFError) as exc:
            raise CaptureError('invalid capture encoding') from exc
        finally:
            path.unlink()
    return records,rejected


def record_response(networks,key,target,responder,same_is_internal=True):
    bucket=networks.setdefault(key,{'network':key,'internal':set(),'external':set()})
    if target==responder:
        if not same_is_internal:
            return None
        role='internal'
    else:
        role='external'
    bucket[role].add(responder)
    return role


def classify(records,leases,at,low):
    """TODO: reconcile lease-scoped discovery roles and quarantine state."""
    raise NotImplementedError('campaign classification')


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("aliases_file",
                        help="text file of aliased /64 prefixes (4 colon groups)")
    parser.add_argument("zmap_csv",
                        help="ZMap6 output CSV.zst (saddr,...,responder,...)")
    args = parser.parse_args()

    aliases = set()
    with open(args.aliases_file) as f:
        for line in f:
            aliases.add(line.strip())

    networks: dict[str, dict] = {}
    for row in stream_csv(args.zmap_csv):
        fields = row.split(",")
        if len(fields) < 2:
            continue
        target, responder = fields[0], fields[1]
        try:
            exploded = ipaddress.IPv6Address(target).exploded
        except ipaddress.AddressValueError:
            continue
        net64 = ":".join(exploded.split(":")[:4])
        if net64 in aliases:
            continue
        record_response(networks,net64,target,responder)

    for entry in networks.values():
        entry["internal"] = sorted(entry["internal"])
        entry["external"] = sorted(entry["external"])
        print(json.dumps(entry))


if __name__ == "__main__":
    main()

