"""Offline ADB and length-prefixed plist exchange parsing."""
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError


def checksum(data):
    total=0
    for byte in data:
        total=(total+byte)&0xffffffff
    return total


def send_connect():
    command=0x4e584e43
    identity=b'host::zgrab2'
    return struct.pack('<6I',command,0x01000000,4096,len(identity),
                       checksum(identity),command^0xffffffff)+identity


def send_close():
    command=0x45534c43
    return struct.pack('<6I',command,0,0,0,0,command^0xffffffff)


def read_adb_response(data):
    if len(data)<24:
        raise ValueError('short ADB header')
    command,arg0,arg1,length,check,magic=struct.unpack('<6I',data[:24])
    if command^magic!=0xffffffff:
        raise ValueError('bad ADB header')
    if command==0x4e584e43:
        banner=data[24:].decode('utf-8')
        version=f'{(arg0>>16)&255}.{(arg0>>8)&255}.{arg0&255}'
        return ('CNXN',version,banner)
    return ('AUTH',arg0,arg1,data[24:].hex())


GET_VERSION=0
GET_PRODUCT_NAME=1
USBMUXD_COMMANDS={
    GET_VERSION:('ProductVersion','GetValue'),
    GET_PRODUCT_NAME:('ProductName','GetValue')}


def get_value_request(kind):
    key,request=USBMUXD_COMMANDS[kind]
    value=plistlib.dumps({'Key':key,'Label':'usbmuxd','ProtocolVersion':'2',
                         'Request':request},fmt=plistlib.FMT_XML,sort_keys=False)
    return struct.pack('>I',len(value))+value


def get_plists(stream,kind):
    header=stream.read(4)
    size=struct.unpack('>I',header)[0]
    if size==0 or size>65532:
        raise ValueError('invalid plist length')
    body=stream.read(size)
    value=plistlib.loads(body)
    expected=USBMUXD_COMMANDS[kind][0]
    if (type(value) is not dict or set(value)!={'Key','Request','Value'}
            or value['Key']!=expected or value['Request']!='GetValue'
            or type(value['Value']) is not str or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def send_messages(data):
    stream=io.BytesIO(data)
    version=get_plists(stream,GET_VERSION)
    product=get_plists(stream,GET_PRODUCT_NAME)
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync',version,product)


def signature(kind,data):
    try:
        if kind=='tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind=='adb':
            return read_adb_response(data)
        return send_messages(data)
    except (ValueError,UnicodeError,OverflowError,TypeError,plistlib.InvalidFileException,ExpatError):
        return None


def probe_script(kind):
    import base64
    encode=lambda b:base64.b64encode(b).decode('ascii')
    if kind=='tcp':
        return [],[]
    if kind=='adb':
        return [encode(send_connect())],[encode(send_close())]
    return [encode(get_value_request(GET_VERSION)),encode(get_value_request(GET_PRODUCT_NAME))],[]

#!/usr/bin/env python3
"""Public sanity cases through bounded child processes and ordinary OS pipes."""
import json,os,signal,subprocess,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from _bounded import CandidateFailure,execute
from bootstrap import install
from _tree import freeze_tree,temporary_tree
from _json_result import check_result


def interrupted(signum,frame):
    for sig in (signal.SIGINT,signal.SIGTERM):signal.signal(sig,signal.SIG_IGN)
    raise KeyboardInterrupt('public check interrupted')


def main():
    if os.geteuid()==0:raise RuntimeError('run the public checker as a nonroot user')
    if len(sys.argv)!=2:raise RuntimeError('usage: python3 public_check.py /workspace/submission')
    for sig in (signal.SIGINT,signal.SIGTERM):signal.signal(sig,interrupted)
    root=Path(__file__).resolve().parent
    scratch=Path(os.environ.get('TMPDIR','/workspace/tmp'));scratch.mkdir(exist_ok=True)
    results=[]
    with temporary_tree(prefix='public-campaign-',dir=scratch) as directory:
        run=Path(directory)
        digest=freeze_tree(Path(sys.argv[1]),run/'submission')
        install(root/'wheels',run/'deps')
        cases=json.loads((root/'examples/fixtures.json').read_text())
        for case in cases:
            with temporary_tree(prefix='case-',dir=run) as work:
                raw=case['raw'].encode() if 'raw' in case else json.dumps(case['input']).encode()
                try:
                    out,err,seconds=execute(run/'submission/campaign.py',raw,Path(work))
                    check_result(out,case['expected'])
                    passed=True
                    reason='correct'
                except (CandidateFailure,ValueError,UnicodeError) as exc:
                    passed=False;seconds=None;reason=str(exc)
                results.append({'name':case['name'],'passed':passed,'seconds':seconds,'reason':reason})
                # A failed public sanity case suffices; never run another full
                # deadline after a candidate has already failed.
                if not passed:break
    passed=len(results)==len(cases) and all(r['passed'] for r in results)
    print(json.dumps({'public_checks_passed':passed,'submission_sha256':digest,'results':results},sort_keys=True))
    return 0 if passed else 1


if __name__=='__main__':
    try:raise SystemExit(main())
    except KeyboardInterrupt:
        print('Public check interrupted; no result.',file=sys.stderr);raise SystemExit(130)
    except CandidateFailure as exc:
        print(json.dumps({'public_checks_passed':False,'reason':str(exc)}));raise SystemExit(1)
    except MemoryError:
        print('Infrastructure error: trusted checker allocation failed; no result.',file=sys.stderr);raise SystemExit(3)
    except (OSError,RuntimeError,subprocess.SubprocessError) as exc:
        print('Infrastructure error: '+str(exc),file=sys.stderr);raise SystemExit(3)

