def chunked(rng, data, n=3):
    cuts = sorted(rng.randrange(0, len(data) + 1) for _ in range(n - 1))
    out, prev = [], 0
    for c in cuts + [len(data)]:
        out.append(data[prev:c])
        prev = c
    return [b64(c) for c in out]


