#!/usr/bin/env python3
"""Group ZMap6 responses by /64 network and classify each as internal or external.

A response is "internal" when the responder address equals the probed
target — the probe came back from the address we aimed at. It is
"external" when a different address responded (typically a CPE,
router, or NAT64 box on a neighboring address).

Aliased /64 prefixes listed in `aliases_file` are skipped, since they
respond to every probe and would pollute the classification.

Output: JSON Lines on stdout, one record per /64 network:

    {"network": "<4 colon groups>", "internal": [...], "external": [...]}

Usage:
    classify-responses.py aliases.txt zmap-output.csv.zst > networks.jsonl
"""
import argparse
import csv
import io
import ipaddress
import json

import zstandard as zstd
from common import COLUMNS,CaptureError,Invalid,decode64
from ledger import parse_record


def stream_csv(path,encoding='zstd',budget=None,logical_records=False):
    with open(path, "rb") as fh:
        reader=(zstd.ZstdDecompressor().stream_reader(fh,read_across_frames=True)
                if encoding=='zstd' else fh)
        bounded=io.BufferedReader(BoundedReader(reader,budget)) if budget is not None else reader
        with io.TextIOWrapper(bounded,encoding='utf-8',newline='') as text:
            if logical_records:
                yield from csv.reader(text,strict=True)
            else:
                for line in text:
                    if line.startswith('saddr'):
                        continue
                    yield line


class BoundedReader(io.RawIOBase):
    def __init__(self,source,budget):
        self.source=source
        self.budget=budget

    def readable(self):
        return True

    def readinto(self,buffer):
        block=self.source.read(min(len(buffer),self.budget[0]+1))
        self.budget[0]-=len(block)
        if self.budget[0]<0:
            raise CaptureError('decompressed byte budget')
        buffer[:len(block)]=block
        return len(block)


def complete_frames(data):
    """Validate complete dictionary-free bounded-window Zstandard framing."""
    at=0
    while at<len(data):
        if at+4>len(data):raise CaptureError('truncated Zstandard magic')
        magic=int.from_bytes(data[at:at+4],'little')
        if 0x184d2a50<=magic<=0x184d2a5f:
            if at+8>len(data):raise CaptureError('truncated skippable frame')
            size=int.from_bytes(data[at+4:at+8],'little');at+=8+size
            if at>len(data):raise CaptureError('truncated skippable frame')
            continue
        if magic!=0xfd2fb528 or at+5>len(data):raise CaptureError('invalid Zstandard frame')
        flag=data[at+4]
        if flag&0x08:raise CaptureError('reserved Zstandard frame bit')
        single=bool(flag&0x20)
        dictionary=(0,1,2,4)[flag&3]
        content=(1 if single else 0,2,4,8)[flag>>6]
        header=5+(not single)+dictionary+content
        if at+header>len(data):raise CaptureError('truncated Zstandard header')
        params=zstd.get_frame_parameters(data[at:at+header])
        if params.dict_id or params.window_size>128*1024**2:
            raise CaptureError('unsupported dictionary or window')
        at+=header
        while True:
            if at+3>len(data):raise CaptureError('truncated Zstandard block')
            block=int.from_bytes(data[at:at+3],'little');at+=3
            kind=(block>>1)&3;size=block>>3
            if kind==3:raise CaptureError('reserved Zstandard block type')
            at+=1 if kind==1 else size
            if at>len(data):raise CaptureError('truncated Zstandard block')
