        if net64 in aliases:
            continue
        record_response(networks,net64,target,responder)

    for entry in networks.values():
        entry["internal"] = sorted(entry["internal"])
        entry["external"] = sorted(entry["external"])
        print(json.dumps(entry))


if __name__ == "__main__":
    main()

